import java.nio.ByteBuffer;
import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.security.SecureRandom;
import javax.crypto.Mac;
import javax.crypto.spec.SecretKeySpec;
import java.util.Arrays;
import java.util.Base64;

public class SecurePacketProcessor {
    private static final int HEADER_SIZE = 16;
    private static final int HMAC_SIZE = 32;
    private static final int MAX_PACKET_SIZE = 65536;
    private static final int VERSION = 2;

    private final byte[] secretKey;
    private final SecureRandom random;

    public SecurePacketProcessor(byte[] key) {
        if (key == null || key.length < 32) {
            throw new IllegalArgumentException("Key must be at least 32 bytes");
        }
        this.secretKey = key.clone();
        this.random = new SecureRandom();
    }

    /**
     * Packet format:
     * [0-3]   magic (4 bytes): 0xDEADBEEF
     * [4]     version (1 byte)
     * [5]     flags (1 byte)
     * [6-7]   headerExtLen (2 bytes, unsigned short)
     * [8-9]   payloadLen (2 bytes, unsigned short)  
     * [10-11] paddingLen (2 bytes, unsigned short)
     * [12-15] sequence (4 bytes)
     * [16 .. 16+headerExtLen-1] header extension
     * [16+headerExtLen .. 16+headerExtLen+payloadLen-1] payload
     * [16+headerExtLen+payloadLen .. 16+headerExtLen+payloadLen+paddingLen-1] padding
     * [last 32 bytes] HMAC-SHA256
     */

    public static class ProcessedPacket {
        public final byte[] payload;
        public final byte[] headerExtension;
        public final int sequence;
        public final byte flags;

        public ProcessedPacket(byte[] payload, byte[] headerExtension, int sequence, byte flags) {
            this.payload = payload;
            this.headerExtension = headerExtension;
            this.sequence = sequence;
            this.flags = flags;
        }
    }

    private byte[] computeHmac(byte[] data, int offset, int length) {
        try {
            Mac mac = Mac.getInstance("HmacSHA256");
            mac.init(new SecretKeySpec(secretKey, "HmacSHA256"));
            mac.update(data, offset, length);
            return mac.doFinal();
        } catch (Exception e) {
            throw new RuntimeException("HMAC computation failed", e);
        }
    }

    private boolean constantTimeEquals(byte[] a, byte[] b) {
        if (a.length != b.length) return false;
        int result = 0;
        for (int i = 0; i < a.length; i++) {
            result |= a[i] ^ b[i];
        }
        return result == 0;
    }

    /**
     * Process an incoming packet: validate, verify HMAC, extract payload.
     */
    public ProcessedPacket processPacket(byte[] packet) {
        // Basic size validation
        if (packet == null || packet.length < HEADER_SIZE + HMAC_SIZE) {
            return null;
        }
        if (packet.length > MAX_PACKET_SIZE) {
            return null;
        }

        // Check magic
        if (packet[0] != (byte)0xDE || packet[1] != (byte)0xAD || 
            packet[2] != (byte)0xBE || packet[3] != (byte)0xEF) {
            return null;
        }

        // Check version
        if (packet[4] != VERSION) {
            return null;
        }

        // Parse lengths as unsigned shorts
        int headerExtLen = ((packet[6] & 0xFF) << 8) | (packet[7] & 0xFF);
        int payloadLen = ((packet[8] & 0xFF) << 8) | (packet[9] & 0xFF);
        int paddingLen = ((packet[10] & 0xFF) << 8) | (packet[11] & 0xFF);

        // Validate individual lengths
        if (headerExtLen > 1024) return null;
        if (payloadLen > 60000) return null;
        if (paddingLen > 256) return null;

        // Calculate total and validate - use long to prevent any overflow
        long totalDataLenL = (long)HEADER_SIZE + headerExtLen + payloadLen + paddingLen;
        if (totalDataLenL + HMAC_SIZE != packet.length) {
            return null;
        }
        int totalDataLen = (int)totalDataLenL;

        // HMAC verification over the data portion
        byte[] expectedHmac = computeHmac(packet, 0, totalDataLen);
        byte[] actualHmac = new byte[HMAC_SIZE];
        System.arraycopy(packet, totalDataLen, actualHmac, 0, HMAC_SIZE);

        if (!constantTimeEquals(expectedHmac, actualHmac)) {
            return null;
        }

        // Extract fields after HMAC verification succeeds
        byte flags = packet[5];
        int sequence = ((packet[12] & 0xFF) << 24) | ((packet[13] & 0xFF) << 16) |
                      ((packet[14] & 0xFF) << 8) | (packet[15] & 0xFF);

        byte[] headerExt = null;
        if (headerExtLen > 0) {
            headerExt = new byte[headerExtLen];
            System.arraycopy(packet, HEADER_SIZE, headerExt, 0, headerExtLen);
        }

        byte[] payload = null;
        if (payloadLen > 0) {
            payload = new byte[payloadLen];
            System.arraycopy(packet, HEADER_SIZE + headerExtLen, payload, 0, payloadLen);
        }

        return new ProcessedPacket(payload, headerExt, sequence, flags);
    }

    /**
     * Process a batch of concatenated packets from a stream.
     * Each packet is prefixed with a 4-byte big-endian length.
     */
    public ProcessedPacket[] processBatch(byte[] stream) {
        if (stream == null || stream.length < 4) return null;

        java.util.List<ProcessedPacket> results = new java.util.ArrayList<>();
        int pos = 0;

        while (pos + 4 <= stream.length) {
            int pktLen = ((stream[pos] & 0xFF) << 24) | ((stream[pos+1] & 0xFF) << 16) |
                        ((stream[pos+2] & 0xFF) << 8) | (stream[pos+3] & 0xFF);
            pos += 4;

            if (pktLen <= 0 || pktLen > MAX_PACKET_SIZE) break;
            if (pos + pktLen > stream.length) break;

            byte[] packet = new byte[pktLen];
            System.arraycopy(stream, pos, packet, 0, pktLen);
            pos += pktLen;

            ProcessedPacket result = processPacket(packet);
            if (result != null) {
                results.add(result);
            }
        }

        return results.toArray(new ProcessedPacket[0]);
    }

    /**
     * Create a signed packet for transmission.
     */
    public byte[] createPacket(byte[] payload, byte[] headerExt, int sequence, byte flags) {
        if (payload == null) payload = new byte[0];
        if (headerExt == null) headerExt = new byte[0];
        if (payload.length > 60000) throw new IllegalArgumentException("Payload too large");
        if (headerExt.length > 1024) throw new IllegalArgumentException("Header extension too large");

        int paddingLen = 16 - ((HEADER_SIZE + headerExt.length + payload.length) % 16);
        if (paddingLen == 16) paddingLen = 0;

        int totalDataLen = HEADER_SIZE + headerExt.length + payload.length + paddingLen;
        byte[] packet = new byte[totalDataLen + HMAC_SIZE];

        // Write header
        packet[0] = (byte)0xDE; packet[1] = (byte)0xAD;
        packet[2] = (byte)0xBE; packet[3] = (byte)0xEF;
        packet[4] = VERSION;
        packet[5] = flags;
        packet[6] = (byte)(headerExt.length >> 8); packet[7] = (byte)(headerExt.length & 0xFF);
        packet[8] = (byte)(payload.length >> 8); packet[9] = (byte)(payload.length & 0xFF);
        packet[10] = (byte)(paddingLen >> 8); packet[11] = (byte)(paddingLen & 0xFF);
        packet[12] = (byte)(sequence >> 24); packet[13] = (byte)(sequence >> 16);
        packet[14] = (byte)(sequence >> 8); packet[15] = (byte)(sequence & 0xFF);

        // Write data sections
        System.arraycopy(headerExt, 0, packet, HEADER_SIZE, headerExt.length);
        System.arraycopy(payload, 0, packet, HEADER_SIZE + headerExt.length, payload.length);

        // Fill padding with random bytes
        byte[] padding = new byte[paddingLen];
        random.nextBytes(padding);
        System.arraycopy(padding, 0, packet, HEADER_SIZE + headerExt.length + payload.length, paddingLen);

        // Compute and append HMAC
        byte[] hmac = computeHmac(packet, 0, totalDataLen);
        System.arraycopy(hmac, 0, packet, totalDataLen, HMAC_SIZE);

        return packet;
    }
}
